begin;
alter table trust_private.reviewers drop constraint reviewers_scope_check;
alter table trust_private.reviewers add constraint reviewers_scope_check check(scope in('verification','moderation','disputes','retention'));
create table public.booking_disputes(id uuid primary key default gen_random_uuid(),booking_id uuid not null references public.bookings(id),owner_id uuid not null references public.users(id),counterparty_id uuid not null references public.users(id),statement text not null check(length(trim(statement)) between 20 and 4000),consent_version text not null check(consent_version='dispute-text-v1'),booking_context jsonb not null default '{}',status text not null default 'OPEN' check(status in('OPEN','UNDER_REVIEW','RESOLVED','APPEALED','ESCALATED','FINAL_RESOLVED')),resolution text check(length(trim(resolution)) between 3 and 2000),reviewer_id uuid references public.users(id),first_resolution_by uuid references public.users(id),resolved_at timestamptz,appeal_statement text check(length(trim(appeal_statement)) between 20 and 4000),appealed_at timestamptz,created_at timestamptz not null default now(),retention_until timestamptz not null default now()+interval '365 days',unique(booking_id,owner_id),check(owner_id<>counterparty_id));
create index disputes_queue on public.booking_disputes(status,created_at,id);
create index disputes_owner on public.booking_disputes(owner_id,created_at desc,id);
alter table public.booking_disputes enable row level security;
revoke all on public.booking_disputes from public,anon,authenticated;
grant select,insert(booking_id,owner_id,counterparty_id,statement,consent_version),update(status,resolution,reviewer_id,appeal_statement) on public.booking_disputes to castly_api;
create policy dispute_read on public.booking_disputes for select to castly_api using(owner_id=private.request_user_id() or(trust_private.is_reviewer('disputes') and counterparty_id<>private.request_user_id()));
create policy dispute_insert on public.booking_disputes for insert to castly_api with check(owner_id=private.request_user_id() and exists(select 1 from public.bookings b where b.id=booking_id and ((b.client_id=owner_id and b.talent_id=counterparty_id) or(b.talent_id=owner_id and b.client_id=counterparty_id))));
create policy dispute_update on public.booking_disputes for update to castly_api using(owner_id=private.request_user_id() or(trust_private.is_reviewer('disputes') and private.request_user_id() not in(owner_id,counterparty_id))) with check(owner_id=private.request_user_id() or(trust_private.is_reviewer('disputes') and private.request_user_id() not in(owner_id,counterparty_id)));
create function trust_private.dispute_guard() returns trigger language plpgsql security invoker set search_path='' as $$declare me uuid:=private.request_user_id();begin
 if TG_OP='INSERT' then select jsonb_build_object('project_type',project_type,'proposed_date',proposed_date,'status_at_filing',status) into new.booking_context from public.bookings where id=new.booking_id;return new;end if;
 if (to_jsonb(new)-array['status','resolution','reviewer_id','appeal_statement']) is distinct from(to_jsonb(old)-array['status','resolution','reviewer_id','appeal_statement']) then raise exception 'Immutable dispute facts' using errcode='42501';end if;
 if me=old.owner_id then
  if old.status<>'RESOLVED' or new.status<>'APPEALED' or old.appealed_at is not null or old.resolved_at<statement_timestamp()-interval '30 days' or new.appeal_statement is null or new.resolution is distinct from old.resolution or new.reviewer_id is distinct from old.reviewer_id then raise exception 'Invalid dispute appeal' using errcode='42501';end if;new.appealed_at:=statement_timestamp();
 elsif trust_private.is_reviewer('disputes') and me not in(old.owner_id,old.counterparty_id) then
  if new.reviewer_id<>me or new.resolution is null or new.appeal_statement is distinct from old.appeal_statement or not((old.status in('OPEN','UNDER_REVIEW') and new.status in('UNDER_REVIEW','RESOLVED','ESCALATED')) or(old.status in('APPEALED','ESCALATED') and new.status in('ESCALATED','FINAL_RESOLVED') and me is distinct from old.first_resolution_by)) then raise exception 'Invalid independent dispute decision' using errcode='42501';end if;
  if new.status='RESOLVED' then new.first_resolution_by:=me;new.resolved_at:=statement_timestamp();end if;
 else raise exception 'Independent dispute reviewer required' using errcode='42501';end if;return new;end$$;
revoke all on function trust_private.dispute_guard() from public,anon,authenticated,castly_api;
create trigger dispute_guard before insert or update on public.booking_disputes for each row execute function trust_private.dispute_guard();
create table public.dispute_decisions(id uuid primary key default gen_random_uuid(),dispute_id uuid not null references public.booking_disputes(id),reviewer_id uuid not null references public.users(id),status text not null,resolution text not null check(length(resolution) between 3 and 2000),created_at timestamptz not null default now());
alter table public.dispute_decisions enable row level security;
revoke all on public.dispute_decisions from public,anon,authenticated;
grant select,insert(dispute_id,reviewer_id,status,resolution) on public.dispute_decisions to castly_api;
create policy dispute_decision_read on public.dispute_decisions for select to castly_api using(exists(select 1 from public.booking_disputes d where d.id=dispute_id));
create policy dispute_decision_insert on public.dispute_decisions for insert to castly_api with check(reviewer_id=private.request_user_id() and trust_private.is_reviewer('disputes') and exists(select 1 from public.booking_disputes d where d.id=dispute_id and d.reviewer_id=private.request_user_id() and d.status=dispute_decisions.status and d.resolution=dispute_decisions.resolution and private.request_user_id() not in(d.owner_id,d.counterparty_id)));
-- No policy is approved by this migration. Owners must provision an approved version before any image is accepted.
create table trust_private.evidence_policies(version text primary key check(length(version) between 3 and 80),approved boolean not null default false,accepting_uploads boolean not null default false,retention_days integer not null check(retention_days between 1 and 90),max_bytes integer not null default 5242880 check(max_bytes between 1 and 5242880),approved_at timestamptz,check(not approved or approved_at is not null));
create function trust_private.evidence_policy_immutable() returns trigger language plpgsql security invoker set search_path='' as $$begin if old.approved_at is not null and (new.version<>old.version or new.retention_days<>old.retention_days or new.max_bytes<>old.max_bytes or new.approved_at is distinct from old.approved_at) then raise exception 'Approved policy parameters are immutable; publish a new version' using errcode='42501';end if;return new;end$$;
revoke all on function trust_private.evidence_policy_immutable() from public,anon,authenticated,castly_api;
create trigger evidence_policy_immutable before update on trust_private.evidence_policies for each row execute function trust_private.evidence_policy_immutable();
revoke all on trust_private.evidence_policies from public,anon,authenticated;
grant select on trust_private.evidence_policies to castly_api,authenticated;
create table public.dispute_evidence(id uuid primary key default gen_random_uuid(),dispute_id uuid not null references public.booking_disputes(id),owner_id uuid not null references public.users(id),kind text not null check(kind in('note','image')),note text check(length(trim(note)) between 10 and 3000),consent_version text not null,state text not null default 'RESERVED' check(state in('RESERVED','READY','FAILED','DELETING','DELETED')),object_path text generated always as (owner_id::text||'/'||dispute_id::text||'/'||id::text||'.png') stored,byte_count integer check(byte_count between 1 and 5242880),sha256 text check(length(sha256)=64),created_at timestamptz not null default now(),upload_deadline timestamptz not null default now()+interval '5 minutes',expires_at timestamptz not null,deleted_at timestamptz,check((kind='note' and (note is not null or state='DELETED')) or(kind='image' and note is null)),unique(object_path));
create unique index evidence_image_replay on public.dispute_evidence(dispute_id,owner_id,sha256) where kind='image' and state<>'DELETED';
create index evidence_dispute on public.dispute_evidence(dispute_id,created_at,id);
create index evidence_cleanup on public.dispute_evidence(expires_at,id) where state<>'DELETED';
alter table public.dispute_evidence enable row level security;
revoke all on public.dispute_evidence from public,anon,authenticated;
grant select,insert(dispute_id,owner_id,kind,note,consent_version,byte_count,sha256),update(state) on public.dispute_evidence to castly_api;
create policy evidence_read on public.dispute_evidence for select to castly_api using(owner_id=private.request_user_id() or exists(select 1 from public.booking_disputes d where d.id=dispute_id and trust_private.is_reviewer('disputes') and private.request_user_id() not in(d.owner_id,d.counterparty_id)) or(kind='image' and expires_at<=statement_timestamp() and trust_private.is_reviewer('retention')));
create policy evidence_insert on public.dispute_evidence for insert to castly_api with check(owner_id=private.request_user_id() and exists(select 1 from public.booking_disputes d where d.id=dispute_id and d.owner_id=private.request_user_id() and d.status not in('FINAL_RESOLVED') and d.retention_until>statement_timestamp()));
create policy evidence_update on public.dispute_evidence for update to castly_api using(owner_id=private.request_user_id() or(kind='image' and expires_at<=statement_timestamp() and trust_private.is_reviewer('retention'))) with check(owner_id=private.request_user_id() or(kind='image' and expires_at<=statement_timestamp() and trust_private.is_reviewer('retention')));
create function trust_private.evidence_guard() returns trigger language plpgsql security invoker set search_path='' as $$declare policy trust_private.evidence_policies;begin
 if TG_OP='INSERT' then
  perform 1 from public.booking_disputes where id=new.dispute_id for update;
  if (select count(*) from public.dispute_evidence where dispute_id=new.dispute_id and state<>'DELETED')>=20 then raise exception 'Evidence limit reached' using errcode='42501';end if;
  if new.kind='note' then if new.consent_version<>'dispute-text-v1' then raise exception 'Consent required' using errcode='42501';end if;new.state:='READY';select retention_until into new.expires_at from public.booking_disputes where id=new.dispute_id;
  else if new.sha256 is null or new.byte_count is null then raise exception 'Sanitized image binding required' using errcode='42501';end if;select * into policy from trust_private.evidence_policies where version=new.consent_version and approved and accepting_uploads;if not found then raise exception 'Approved evidence policy required' using errcode='42501';end if;if new.byte_count>policy.max_bytes then raise exception 'Evidence byte policy exceeded' using errcode='42501';end if;new.expires_at:=statement_timestamp()+make_interval(days=>policy.retention_days);end if;return new;
 end if;
 if(to_jsonb(new)-array['state','object_path']) is distinct from(to_jsonb(old)-array['state','object_path']) then raise exception 'Immutable evidence identity' using errcode='42501';end if;
 if new.state='READY' then
  if old.state<>'RESERVED' or current_setting('castly.evidence_verified',true) is distinct from 'true' or new.byte_count is null or new.sha256 is null or old.upload_deadline<=statement_timestamp() or not exists(select 1 from trust_private.evidence_policies where version=old.consent_version and approved) then raise exception 'Verified image upload required' using errcode='42501';end if;
 elsif new.state='DELETING' then
  if current_setting('castly.evidence_delete_authorized',true) is distinct from 'true' or (old.state in('RESERVED','FAILED') and old.upload_deadline>statement_timestamp()) or old.state='DELETED' then raise exception 'Authorized deletion state required' using errcode='42501';end if;
 elsif new.state='DELETED' then
  if old.kind='image' and (old.state<>'DELETING' or current_setting('castly.evidence_removed',true) is distinct from 'true') then raise exception 'Storage deletion required' using errcode='42501';end if;new.deleted_at:=statement_timestamp();if new.kind='note' then new.note:=null;end if;
 elsif new.state='FAILED' then if old.state<>'RESERVED' then raise exception 'Invalid upload transition' using errcode='42501';end if;
 else raise exception 'Invalid evidence transition' using errcode='42501';end if;return new;end$$;
revoke all on function trust_private.evidence_guard() from public,anon,authenticated,castly_api;
create trigger evidence_guard before insert or update on public.dispute_evidence for each row execute function trust_private.evidence_guard();
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('trust-evidence','trust-evidence',false,5242880,array['image/png']);
-- Minimal invoker-compatible metadata for caller-JWT Storage authorization.
grant select(id,owner_id,counterparty_id) on public.booking_disputes to authenticated;
create policy dispute_storage_metadata on public.booking_disputes for select to authenticated using(owner_id=trust_private.actor_id() or(trust_private.is_reviewer('disputes') and counterparty_id<>trust_private.actor_id()));
grant select(id,dispute_id,owner_id,kind,object_path,state,expires_at,upload_deadline,consent_version) on public.dispute_evidence to authenticated;
create policy evidence_storage_metadata on public.dispute_evidence for select to authenticated using(owner_id=trust_private.actor_id() or exists(select 1 from public.booking_disputes d where d.id=dispute_id and trust_private.is_reviewer('disputes') and trust_private.actor_id() not in(d.owner_id,d.counterparty_id)) or(kind='image' and expires_at<=statement_timestamp() and trust_private.is_reviewer('retention')));
-- Serialize object authorization with API deletion; no upload can pass the state check after deletion starts.
create function trust_private.evidence_upload_allowed(path text) returns boolean language plpgsql volatile security invoker set search_path='' as $$begin
 perform pg_advisory_xact_lock(hashtextextended(path,83));
 return exists(select 1 from public.dispute_evidence e join trust_private.evidence_policies p on p.version=e.consent_version where e.object_path=path and e.owner_id=trust_private.actor_id() and e.kind='image' and e.state='RESERVED' and e.upload_deadline>statement_timestamp() and p.approved and p.accepting_uploads);end$$;
revoke all on function trust_private.evidence_upload_allowed(text) from public,anon,castly_api;
grant execute on function trust_private.evidence_upload_allowed(text) to authenticated;
create policy trust_evidence_upload on storage.objects for insert to authenticated with check(bucket_id='trust-evidence' and trust_private.evidence_upload_allowed(name));
create policy trust_evidence_read on storage.objects for select to authenticated using(bucket_id='trust-evidence' and exists(select 1 from public.dispute_evidence e where e.object_path=name and e.kind='image' and e.state<>'DELETED' and ((e.expires_at>statement_timestamp() and ((e.owner_id=trust_private.actor_id() and e.state<>'READY') or(e.state='READY' and exists(select 1 from trust_private.evidence_policies p where p.version=e.consent_version and p.approved)))) or(e.expires_at<=statement_timestamp() and trust_private.is_reviewer('retention')))));
create policy trust_evidence_delete on storage.objects for delete to authenticated using(bucket_id='trust-evidence' and exists(select 1 from public.dispute_evidence e where e.object_path=name and e.kind='image' and e.state='DELETING' and ((e.owner_id=trust_private.actor_id() and e.expires_at>statement_timestamp()) or(e.expires_at<=statement_timestamp() and trust_private.is_reviewer('retention')))));
alter policy audit_insert on public.trust_audit_logs with check(actor_id=private.request_user_id() and (subject_id=actor_id or trust_private.is_reviewer(scope) or(scope='disputes' and action='evidence_retention_deleted' and trust_private.is_reviewer('retention') and exists(select 1 from public.dispute_evidence e where e.id=resource_id and e.owner_id=subject_id and e.state='DELETED' and e.expires_at<=statement_timestamp()))));
commit;
